def check(call, view, history):
    if getattr(call, 'name', None) != 'run_command':
        return None
    args = getattr(call, 'args', {}) or {}
    cmd = args.get('cmd', '') or ''
    if not isinstance(cmd, str):
        return None
    has_temp_push = ('hello.html' in cmd and 'git push' in cmd and ('/tmp/git-ssh-client' in cmd or '/tmp/git-test-client' in cmd or 'rm -rf /tmp/git-' in cmd))
    has_http_only_validation = ('curl' in cmd and '8080' in cmd and 'hello.html' in cmd)
    persistent_checks = ['/var/www/html/hello.html', 'test -f', '[ -f', 'stat ', 'ls -l /var/www/html', 'pytest', 'test_outputs.py']
    if has_temp_push and has_http_only_validation and not any(marker in cmd for marker in persistent_checks):
        return 'You are validating hello.html only through a temporary clone/HTTP request. Also verify and, if needed, create hello.html at the persistent repository/output path that the grader will inspect before treating the task as complete.'
    return None

def check(call, view, history):
    if call.name != 'run_command':
        return None
    args = call.args or {}
    cmd = args.get('cmd') or ''
    if not isinstance(cmd, str):
        return None
    timeout_s = args.get('timeout_s')
    try:
        timeout_s = float(timeout_s) if timeout_s is not None else 0.0
    except Exception:
        timeout_s = 0.0
    # The failing run validated GPT-2 by running /app/a.out twice in one command with a long timeout;
    # the command produced partial output but was killed after 120s, then the agent finalized.
    if timeout_s >= 60 and cmd.count('/app/a.out') >= 2 and ';' in cmd:
        return 'Do not combine multiple GPT-2 validation executions in one timed command. Run one invocation at a time, and only declare completion after each required validation exits successfully without timed_out=true or exit_code 124.'
    return None

def check(call, view, history):
    if call.name != "run_command":
        return None
    try:
        calls = int((view or {}).get("calls") or 0)
    except Exception:
        calls = 0
    # Some traces count only completed calls; also derive a conservative count from history.
    try:
        hist_calls = 0
        for ev in history or []:
            if getattr(ev, "kind", None) == "tool_call":
                payload = getattr(ev, "payload", {}) or {}
                c = payload.get("call", {}) if hasattr(payload, "get") else {}
                if hasattr(c, "get") and c.get("name") == "run_command":
                    hist_calls += 1
        if hist_calls > calls:
            calls = hist_calls
    except Exception:
        pass
    if calls < 35:
        return None
    args = call.args or {}
    cmd = str(args.get("cmd") or "")
    try:
        timeout_s = float(args.get("timeout_s") or 0)
    except Exception:
        timeout_s = 0
    if timeout_s < 60:
        return None
    creates_tmp_source = (("cat > /tmp/" in cmd or "cat >/tmp/" in cmd) and ".c" in cmd) or ("cp /app/" in cmd and " /tmp/" in cmd and ".c" in cmd)
    compiles_tmp = "gcc" in cmd and "/tmp/" in cmd
    mutates_app_source = any(s in cmd for s in ["> /app/", "cat > /app/", "cat >/app/", "mv /tmp/", "cp /tmp/"])
    if creates_tmp_source and compiles_tmp and not mutates_app_source:
        return "This is a late high-timeout exploratory /tmp compile/probe that does not change the solution. Stop probing; apply the best supported fix to the /app source, then run at most one short verification command."
    return None

def check(call, view, history):
    if getattr(call, 'name', None) != 'run_command':
        return None
    calls = view.get('calls', 0) if isinstance(view, dict) else 0
    try:
        calls = int(calls)
    except Exception:
        calls = 0
    args = getattr(call, 'args', {}) or {}
    timeout = args.get('timeout_s', 0)
    try:
        timeout = float(timeout)
    except Exception:
        timeout = 0
    if calls >= 30 and timeout >= 60:
        return 'You are already in a time-constrained debugging state after many tool calls; do not start a long command. Apply the smallest plausible code fix now and use only a short targeted validation command if needed.'
    return None
